{
  "@context": "https://schema.org",
  "@type": "Thing",
  "name": "{{product.name}}",
  "description": "{{product.short_description | plain | limit:300 | default:'Made by \"Linden\"'}}",
  "postalCode": "01069",
  "count": 12,
  "ratio": 4.50,
  "isAccessibleForFree": true,
  "itemCondition": "https://schema.org/NewCondition",
  "braces": "Write {{{{ and }} as they are",
  "headline": "{{product.name}} by {{store.name}}",
  "comparison": "{{ product.final_price > 10 }}",
  "brand": {
    "@type": "Brand",
    "name": "{{product.manufacturer | default:'O\\'Neill'}}"
  },
  "loose": {
    "name": "Linden"
  },
  "both": {
    "@type": ["Product", "Car"],
    "name": "{{product.name}}"
  },
  "policy": { "@if": "product.on_sale", "@include": "return-policy" },
  "image": {
    "@each": "product.gallery",
    "@as": "picture",
    "@limit": 2,
    "@value": "{{picture.url}}"
  },
  "guarded": {
    "@if": "reviews.count",
    "@value": {
      "@each": "reviews.latest",
      "@value": "{{review.text}}"
    }
  },
  "price": {
    "@if": "product.on_sale",
    "@value": "{{product.final_price}}"
  },
  "tags": [
    "Leather",
    "{{product.sku}}",
    {
      "@if": "product.on_sale",
      "@value": "Sale"
    }
  ],
  "filtered": {
    "@each": "reviews.latest",
    "@if": "review.rating",
    "@value": "{{review.text}}"
  },
  "complex": {
    "@if": "product.on_sale and reviews.count",
    "@type": "Offer"
  },
  "empty": {},
  "nothing": null
}
